const helpRun = await graphql_help({ for: "runtime" });
const helpWatch = await graphql_help({ for: "watches" });
const watchCap = await query_catalog({ id: "capability:gj_watch" });
const mutationRes = await execute_graphql({
  query: `mutation {
    gj_watch(insert: {
      name: "deeporg_churn_accounts",
      query: "subscription deeporg_churn_accounts { churn_risk_accounts(first: 25) { id account_name risk_score } }",
      delivery_json: { kind: "inbox", digest: { window: "1h" } }
    }) {
      id
      status
      enabled
      delivery_json
    }
  }`
});
await final("Successfully created the durable watch named deeporg_churn_accounts with hourly inbox digest delivery for churn-risk accounts.", { mutationRes });

